using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Threading;using System.Windows.Forms;using System.Diagnostics;using System.Collections.Generic;
namespace GearLab {
 public partial class MainForm {
  internal void WaveRegression56(string folder){var report=new List<string>();Action<bool,string> check=(ok,s)=>{if(!ok)throw new Exception(s);report.Add(s);};animation.Stop();var standardMenu=MainMenuStrip;var standardCalculate=calculate;var standardView=view;var timings=new List<double>();int workers=CADKernel.StartedWorkers;
   foreach(int ratio in new[]{50,80,100}){var seed=Engine.Starter(4);seed.Ratio=ratio;var watch=Stopwatch.StartNew();Apply(seed,true);ShowFullModel();var scene=canvas.Viewer.Scene;while(!scene.Ready&&scene.Error==null&&watch.Elapsed.TotalSeconds<10){Application.DoEvents();Thread.Sleep(5);}watch.Stop();check(scene.Ready,"ready fast 3D "+ratio+": "+scene.Error);check(result.Model.Valid,"valid assembly "+ratio);check(scene.Nodes.Count>=17&&scene.TriangleCount>1000,"actual geometry in scene "+ratio);check(scene.Nodes.All(n=>n.Source.SignedVolume()>0),"closed positive preview solids "+ratio);timings.Add(watch.Elapsed.TotalSeconds);check(watch.Elapsed.TotalSeconds<3,"3D preview below three seconds "+ratio);check(CADKernel.StartedWorkers==workers,"preview starts no Python/OCCT worker "+ratio);check(ReferenceEquals(MainMenuStrip,standardMenu)&&ReferenceEquals(calculate,standardCalculate)&&ReferenceEquals(view,standardView),"same menus and controls "+ratio);check(sliders["Ratio"].Visible&&sliders["Overall"].Visible,"common numeric fields and sliders "+ratio);check(Math.Abs(result.Wave.OutputRpm+p.InputRpm/p.Ratio)<1e-8,"negative output speed "+ratio);
    if(ratio==50){scene.SavePng(Path.Combine(folder,"wave-3d.png"),1200,800);ShowModelView(0);Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(folder,"wave-ui.png"));}ShowFullModel();int count=SceneMesher.Builds;var sw=Stopwatch.StartNew();for(int j=0;j<60;j++)scene.UpdatePose(j*.1);sw.Stop();check(SceneMesher.Builds==count,"animation reuses meshed geometry");check(sw.Elapsed.TotalMilliseconds/60<50,"wave animation below 50 ms per frame");var cached=result.Model;numbers["InputTorque"].Commit(.5m);calculate.PerformClick();check(ReferenceEquals(cached,result.Model),"torque edits reuse model");numbers["InputRpm"].Commit(60);calculate.PerformClick();check(ReferenceEquals(cached,result.Model),"RPM edits reuse model");var back=ReleaseSupport.Parse(ReleaseSupport.Serialize(p));check(back.Kind==4&&back.WaveWall==p.WaveWall,"shared gear project roundtrip");}
   }
   foreach(int kind in new[]{0,3,4,1,4}){SetHostedKind(kind);Application.DoEvents();check(p.Kind==kind&&result.Valid,"switch family "+kind);check(MainMenuStrip.Items.Cast<ToolStripItem>().Any(i=>i.Text=="Экспорт"),"shared export menu "+kind);}
   var legacy=new WaveParameters{Ratio=80};string old=Path.Combine(folder,"legacy.wave.json");File.WriteAllText(old,CADDocument.Serializer().Serialize(legacy));var migrated=WaveProjectMigration.Read(old);check(migrated.Kind==4&&migrated.Ratio==80&&migrated.Module==legacy.Module,"old wave project migration");check(CADKernel.StartedWorkers==workers,"entire preview session uses no kernel process");File.WriteAllText(Path.Combine(folder,"reducer56-results.json"),CADDocument.Serializer().Serialize(new{passed=report,preview_seconds=timings.ToArray(),native_workers_started=CADKernel.StartedWorkers-workers}),Encoding.UTF8);
  }
 }
 public static class Reducer56Tests {
  public static int Run(string folder){Directory.CreateDirectory(folder);try{var reducers=new ReducerWorkspaceForm();using(var shell=new WorkspaceShell(reducers)){shell.Show();Application.DoEvents();var common=reducers.MainView;if(common==null)throw new Exception("No main reducer form");reducers.SelectWave();if(!ReferenceEquals(common,reducers.MainView)||shell.Pages.TabCount!=1)throw new Exception("Wave opened another form/page");common.WaveRegression56(folder);shell.ApproveTestClose();shell.Close();}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"reducer56-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
